func classifyItem(s string) RequestItem {
    // Find earliest occurrence of ":=", "==", ":", "="
    idxRaw := strings.Index(s, ":=")
    idxQuery := strings.Index(s, "==")
    // For ":" we need first colon not part of ":="?
    // But our earliest logic should consider ":" position, but if ":=" present at same pos, ":=" wins.
    // Similarly "=" vs "=="
    // So find all positions
    idxColon := strings.Index(s, ":")
    idxEqual := strings.Index(s, "=")

    // Determine earliest
    // We will create list of candidates with index and priority
    // Priority: if same index, longer delimiter wins: ":=" over ":", "==" over "="
    // We'll find minimal index among those present

    // Initialize with large
    minIdx := -1
    chosen := ""
    // candidates
    candidates := []struct{
        idx int
        typ string
    }{}
    if idxRaw != -1 {
        candidates = append(candidates, struct{idx int; typ string}{idxRaw, "rawjson"})
    }
    if idxQuery != -1 {
        candidates = append(candidates, struct{idx int; typ string}{idxQuery, "query"})
    }
    if idxColon != -1 {
        candidates = append(candidates, struct{idx int; typ string}{idxColon, "header"})
    }
    if idxEqual != -1 {
        candidates = append(candidates, struct{idx int; typ string}{idxEqual, "data"})
    }
    if len(candidates)==0 {
        return RequestItem{Raw: s, Type: "bare"}
    }
    // Find minimal idx, with tie-breaking
    // Sort by idx, but with priority for longer when same idx
    // We'll iterate
    minIdx = candidates[0].idx
    chosen = candidates[0].typ
    for _, c := range candidates[1:] {
        if c.idx < minIdx {
            minIdx = c.idx
            chosen = c.typ
        } else if c.idx == minIdx {
            // tie: prefer rawjson over header, query over data, and longer over shorter
            // Define priority: rawjson > header, query > data
            // Also if rawjson and header same idx, rawjson wins
            // If query and data same idx, query wins
            if chosen == "header" && c.typ == "rawjson" {
                chosen = c.typ
            } else if chosen == "data" && c.typ == "query" {
                chosen = c.typ
            } else if chosen == "data" && c.typ == "rawjson" {
                // rawjson : contains :=, but if := and = same idx, := wins
                chosen = c.typ
            } else if chosen == "header" && c.typ == "query" {
                // which wins? Query starts with ==, header with : . If same index? Unlikely because different chars, but if string is "a:==b"? Then : at pos 1, == at pos 2, not same.
                // So tie only occurs for := vs : and == vs =
            }
        }
    }
    // Now based on chosen type, extract key/value
    switch chosen {
    case "rawjson":
        // split at minIdx
        key := s[:minIdx]
        val := s[minIdx+2:]
        return RequestItem{Raw: s, Type: "rawjson", Key: key, Value: val}
    case "query":
        key := s[:minIdx]
        val := s[minIdx+2:]
        return RequestItem{Raw: s, Type: "query", Key: key, Value: val}
    case "header":
        key := s[:minIdx]
        val := s[minIdx+1:]
        return RequestItem{Raw: s, Type: "header", Key: key, Value: val}
    case "data":
        key := s[:minIdx]
        val := s[minIdx+1:]
        return RequestItem{Raw: s, Type: "data", Key: key, Value: val}
    }
    return RequestItem{Raw: s, Type: "bare"}
}

func main() {
