func colorizeHeader(line string, isRequest bool) string {
    // line is like "Server: BaseHTTP/0.6 Python/3.10.12" or "HTTP/1.0 200 OK"
    // For status line: "HTTP/1.0 200 OK"
    // For request line: "GET / HTTP/1.1" or "POST / HTTP/1.1"
    // For header: "Name: value"

    white := "\x1b[37m"
    blue := "\x1b[34m"
    cyan := "\x1b[36m"
    yellow := "\x1b[33m"
    reset := "\x1b[0m"

    // Check if it's status line (starts with HTTP/)
    if strings.HasPrefix(line, "HTTP/") {
        // Format: HTTP/1.0 200 OK
        // Split: HTTP / 1.0 200 OK?
        // We'll parse: "HTTP/" + version + " " + code + " " + reason
        // Using regex: ^(HTTP)/([\d\.]+)\s+(\d+)(.*)
        // But we need to color: HTTP blue, / white, version+code cyan, reason yellow
        // For "HTTP/1.0 200 OK": HTTP blue, / white, "1.0 200" cyan, " OK" yellow
        // Let's try to split
        // Find first "/"
        if idx := strings.Index(line, "/"); idx != -1 {
            // HTTP part before /
            // after /
            rest := line[idx+1:]
            // rest is like "1.0 200 OK"
            // Find code: first space after version?
            // Actually rest starts with version, then space, then code, then space, reason
            // We want to split version+code as cyan, reason as yellow
            // Find last space before reason? Reason may contain spaces? Usually "OK" single word, but could be "Not Found"
            // So: versionAndCode = up to code inclusive? Let's find code is 3 digits?
            // We'll find first space after version, then code, then rest is reason
            parts := strings.Fields(rest)
            // parts[0] = version (1.0), parts[1] = code (200), rest = reason (OK)
            // So cyan part = version + space + code
            // yellow part = space + reason
            version := ""
            code := ""
            reason := ""
            if len(parts)>=1 {
                version = parts[0]
            }
            if len(parts)>=2 {
                code = parts[1]
            }
            if len(parts)>2 {
                reason = strings.Join(parts[2:], " ")
            }
            var out strings.Builder
            out.WriteString(blue + "HTTP" + white + "/" + cyan + version + " " + code)
            if reason != "" {
                out.WriteString(yellow + " " + reason)
            }
            out.WriteString("\r" + reset + "\n")
            return out.String()
        }
    }

    // Check if it's request line: METHOD path HTTP/...
    // Example: "GET / HTTP/1.1"
    // Split by space
    parts := strings.Split(line, " ")
    if len(parts)>=3 && strings.HasPrefix(parts[2], "HTTP/") {
        // method, path, HTTP/...
        method := parts[0]
        path := parts[1]
        httpPart := parts[2] // HTTP/1.1
        // httpPart split by "/"
        var httpOut strings.Builder
        if idx := strings.Index(httpPart, "/"); idx != -1 {
            httpOut.WriteString(blue + "HTTP" + white + "/" + cyan + httpPart[idx+1:])
        } else {
            httpOut.WriteString(httpPart)
        }
        var out strings.Builder
        out.WriteString(blue + method + white + " " + path + " " + httpOut.String() + "\r" + reset + "\n")
        return out.String()
    }

    // Otherwise header: "Name: value"
    if colonIdx := strings.Index(line, ":"); colonIdx != -1 {
        name := line[:colonIdx+1] // include colon
        value := line[colonIdx+1:]
        // value may have leading space
        var out strings.Builder
        out.WriteString(white + name + cyan + value + "\r" + reset + "\n")
        return out.String()
    }

    // Fallback
    return white + line + "\r" + reset + "\n"
}

func colorizeRequestLine(line string) string {
    return colorizeHeader(line, true)
}

