func classifyItem(s string) RequestItem {
    idxRaw := strings.Index(s, ":=")
    idxQuery := strings.Index(s, "==")
    idxColon := strings.Index(s, ":")
    idxEqual := strings.Index(s, "=")

    type cand struct {
        idx int
        typ string
    }
    var candidates []cand
    if idxRaw != -1 {
        candidates = append(candidates, cand{idxRaw, "rawjson"})
    }
    if idxQuery != -1 {
        candidates = append(candidates, cand{idxQuery, "query"})
    }
    if idxColon != -1 {
        candidates = append(candidates, cand{idxColon, "header"})
    }
    if idxEqual != -1 {
        candidates = append(candidates, cand{idxEqual, "data"})
    }
    if len(candidates) == 0 {
        return RequestItem{Raw: s, Type: "bare"}
    }
    minIdx := candidates[0].idx
    chosen := candidates[0].typ
    for _, c := range candidates[1:] {
        if c.idx < minIdx {
            minIdx = c.idx
            chosen = c.typ
        } else if c.idx == minIdx {
            if chosen == "header" && c.typ == "rawjson" {
                chosen = c.typ
            } else if chosen == "data" && c.typ == "query" {
                chosen = c.typ
            } else if chosen == "data" && c.typ == "rawjson" {
                chosen = c.typ
            }
        }
    }
    switch chosen {
    case "rawjson":
        return RequestItem{Raw: s, Type: "rawjson", Key: s[:minIdx], Value: s[minIdx+2:]}
    case "query":
        return RequestItem{Raw: s, Type: "query", Key: s[:minIdx], Value: s[minIdx+2:]}
    case "header":
        return RequestItem{Raw: s, Type: "header", Key: s[:minIdx], Value: s[minIdx+1:]}
    case "data":
        return RequestItem{Raw: s, Type: "data", Key: s[:minIdx], Value: s[minIdx+1:]}
    }
    return RequestItem{Raw: s, Type: "bare"}
}

