    }

    isJSONMode := !formMode
    var jsonData map[string]interface{}
    var jsonDataPresent bool
    jsonData = make(map[string]interface{})
    if isJSONMode {
        for _, d := range dataItems {
            jsonData[d.Key] = d.Value
        }
        for _, rj := range rawJSONItems {
            if rj.Value == "" {
                jsonData[rj.Key] = nil
            } else {
                var v interface{}
                err := json.Unmarshal([]byte(rj.Value), &v)
                if err != nil {
                    jsonData[rj.Key] = nil
                } else {
                    jsonData[rj.Key] = v
                }
            }
        }
        if len(jsonData) > 0 {
            jsonDataPresent = true
        }
    } else {
        for _, rj := range rawJSONItems {
            if rj.Value == "" {
                jsonData[rj.Key] = nil
            } else {
                var v interface{}
                err := json.Unmarshal([]byte(rj.Value), &v)
                if err != nil {
                    jsonData[rj.Key] = nil
                } else {
                    jsonData[rj.Key] = v
                }
            }
        }
        if len(jsonData) > 0 {
            jsonDataPresent = true
        }
    }

    finalDisplayURL := displayURL
    finalCurlURL := curlURL
    if len(queries) > 0 {
        var newParts []string
        for _, q := range queries {
            kEsc := url.QueryEscape(q.Key)
            vEsc := url.QueryEscape(q.Value)
            newParts = append(newParts, kEsc+"="+vEsc)
        }
        baseDisplay := finalDisplayURL
        existingQuery := ""
        if strings.Contains(finalDisplayURL, "?") {
            parts := strings.SplitN(finalDisplayURL, "?", 2)
            baseDisplay = parts[0]
            existingQuery = parts[1]
        }
        var combinedQuery string
        if existingQuery != "" {
            combinedQuery = existingQuery + "&" + strings.Join(newParts, "&")
        } else {
            combinedQuery = strings.Join(newParts, "&")
        }
        if combinedQuery != "" {
            finalDisplayURL = baseDisplay + "?" + combinedQuery
        }
        baseCurl := finalCurlURL
        existingCurlQuery := ""
        if strings.Contains(finalCurlURL, "?") {
            parts := strings.SplitN(finalCurlURL, "?", 2)
            baseCurl = parts[0]
            existingCurlQuery = parts[1]
        }
        var combinedCurlQuery string
        if existingCurlQuery != "" {
            combinedCurlQuery = existingCurlQuery + "&" + strings.Join(newParts, "&")
        } else {
            combinedCurlQuery = strings.Join(newParts, "&")
        }
        if combinedCurlQuery != "" {
            finalCurlURL = baseCurl + "?" + combinedCurlQuery
        } else {
            finalCurlURL = baseCurl
        }
    }

    hasContentType := false
    hasAccept := false
    for _, h := range headers {
        lname := strings.ToLower(strings.TrimSpace(h.Key))
        if lname == "content-type" {
            hasContentType = true
        }
        if lname == "accept" {
            hasAccept = true
        }
    }
    for idx, opt := range curlOpts {
        if opt == "-H" || opt == "--header" {
            if idx+1 < len(curlOpts) {
