                } else {
                    jsonData[rj.Key] = v
                }
            }
        }
        if len(jsonData) > 0 {
            jsonDataPresent = true
        }
    } else {
        for _, rj := range rawJSONItems {
            if rj.Value == "" {
                jsonData[rj.Key] = nil
            } else {
                var v interface{}
                err := json.Unmarshal([]byte(rj.Value), &v)
                if err != nil {
                    jsonData[rj.Key] = nil
                } else {
                    jsonData[rj.Key] = v
                }
            }
        }
        if len(jsonData) > 0 {
            jsonDataPresent = true
        }
    }

    finalDisplayURL := displayURL
    finalCurlURL := curlURL
    if len(queries) > 0 {
        var newParts []string
        for _, q := range queries {
            kEsc := url.QueryEscape(q.Key)
            vEsc := url.QueryEscape(q.Value)
            newParts = append(newParts, kEsc+"="+vEsc)
        }
        baseDisplay := finalDisplayURL
        existingQuery := ""
        if strings.Contains(finalDisplayURL, "?") {
            parts := strings.SplitN(finalDisplayURL, "?", 2)
            baseDisplay = parts[0]
            existingQuery = parts[1]
        }
        var combinedQuery string
        if existingQuery != "" {
            combinedQuery = existingQuery + "&" + strings.Join(newParts, "&")
        } else {
            combinedQuery = strings.Join(newParts, "&")
        }
        if combinedQuery != "" {
            finalDisplayURL = baseDisplay + "?" + combinedQuery
        }
        baseCurl := finalCurlURL
        existingCurlQuery := ""
        if strings.Contains(finalCurlURL, "?") {
            parts := strings.SplitN(finalCurlURL, "?", 2)
            baseCurl = parts[0]
            existingCurlQuery = parts[1]
        }
        var combinedCurlQuery string
        if existingCurlQuery != "" {
            combinedCurlQuery = existingCurlQuery + "&" + strings.Join(newParts, "&")
        } else {
            combinedCurlQuery = strings.Join(newParts, "&")
        }
        if combinedCurlQuery != "" {
            finalCurlURL = baseCurl + "?" + combinedCurlQuery
        } else {
            finalCurlURL = baseCurl
        }
    }

    hasContentType := false
    hasAccept := false
    for _, h := range headers {
        lname := strings.ToLower(strings.TrimSpace(h.Key))
        if lname == "content-type" {
            hasContentType = true
        }
        if lname == "accept" {
            hasAccept = true
        }
    }
    for idx, opt := range curlOpts {
        if opt == "-H" || opt == "--header" {
            if idx+1 < len(curlOpts) {
                hdrVal := curlOpts[idx+1]
                if colonIdx := strings.Index(hdrVal, ":"); colonIdx != -1 {
                    hName := strings.ToLower(strings.TrimSpace(hdrVal[:colonIdx]))
                    if hName == "content-type" {
                        hasContentType = true
                    }
                    if hName == "accept" {
                        hasAccept = true
                    }
                }
            }
        } else if strings.HasPrefix(opt, "-H") && len(opt) > 2 {
            hdrVal := opt[2:]
            if colonIdx := strings.Index(hdrVal, ":"); colonIdx != -1 {
                hName := strings.ToLower(strings.TrimSpace(hdrVal[:colonIdx]))
                if hName == "content-type" {
                    hasContentType = true
                }
                if hName == "accept" {
                    hasAccept = true
                }
            }
        } else if strings.HasPrefix(opt, "--header=") {
            hdrVal := strings.SplitN(opt, "=", 2)[1]
            if colonIdx := strings.Index(hdrVal, ":"); colonIdx != -1 {
                hName := strings.ToLower(strings.TrimSpace(hdrVal[:colonIdx]))
                if hName == "content-type" {
                    hasContentType = true
                }
                if hName == "accept" {
                    hasAccept = true
                }
            }
        }
    }

    var methodFlag []string
    if method != "" {
        if method == "HEAD" {
            methodFlag = []string{"-I"}
        } else {
            methodFlag = []string{"-X", method}
        }
    }

    execArgs := []string{}
    displayParts := []string{"curl"}

    for _, o := range curlOpts {
        execArgs = append(execArgs, o)
        displayParts = append(displayParts, shellQuote(o))
    }
    for _, mf := range methodFlag {
        execArgs = append(execArgs, mf)
        displayParts = append(displayParts, shellQuote(mf))
    }

    if isJSONMode {
        for _, ohb := range orderedHB {
            if ohb.Type == "header" {
                execArgs = append(execArgs, "-H", ohb.Item.Raw)
                displayParts = append(displayParts, "-H", shellQuote(ohb.Item.Raw))
            } else {
                execArgs = append(execArgs, ohb.Raw)
                displayParts = append(displayParts, shellQuote(ohb.Raw))
            }
        }
        if jsonDataPresent {
            keys := make([]string, 0, len(jsonData))
            for k := range jsonData {
                keys = append(keys, k)
            }
            sort.Strings(keys)
            var buf bytes.Buffer
            buf.WriteString("{")
            for idx, k := range keys {
                keyJSON, _ := json.Marshal(k)
                buf.Write(keyJSON)
                buf.WriteString(":")
                valJSON, _ := json.Marshal(jsonData[k])
                buf.Write(valJSON)
                if idx < len(keys)-1 {
                    buf.WriteString(",")
                }
            }
            buf.WriteString("}")
            jsonStr := buf.String()
            execArgs = append(execArgs, "-d", jsonStr)
            displayParts = append(displayParts, "-d", shellQuote(jsonStr))
        }
    } else {
        type OrderedForm struct {
            Type  string
            Raw   string
            Key   string
            Value string
        }
        var orderedForm []OrderedForm
        for _, ri := range requestItems {
            classified := classifyItem(ri)
            if classified.Type == "header" {
                orderedForm = append(orderedForm, OrderedForm{Type: "header", Raw: ri})
            } else if classified.Type == "bare" {
                orderedForm = append(orderedForm, OrderedForm{Type: "bare", Raw: ri})
            } else if classified.Type == "data" {
                orderedForm = append(orderedForm, OrderedForm{Type: "form", Key: classified.Key, Value: classified.Value, Raw: ri})
            }
        }
        for _, of := range orderedForm {
            if of.Type == "header" {
                execArgs = append(execArgs, "-H", of.Raw)
                displayParts = append(displayParts, "-H", shellQuote(of.Raw))
            } else if of.Type == "bare" {
                execArgs = append(execArgs, of.Raw)
                displayParts = append(displayParts, shellQuote(of.Raw))
            } else if of.Type == "form" {
                fv := of.Key + "=" + of.Value
                execArgs = append(execArgs, "-F", fv)
                displayParts = append(displayParts, "-F", shellQuote(fv))
            }
        }
        if jsonDataPresent {
            keys := make([]string, 0, len(jsonData))
            for k := range jsonData {
                keys = append(keys, k)
            }
            sort.Strings(keys)
            var buf bytes.Buffer
            buf.WriteString("{")
            for idx, k := range keys {
                keyJSON, _ := json.Marshal(k)
                buf.Write(keyJSON)
                buf.WriteString(":")
                valJSON, _ := json.Marshal(jsonData[k])
                buf.Write(valJSON)
                if idx < len(keys)-1 {
                    buf.WriteString(",")
                }
            }
            buf.WriteString("}")
            jsonStr := buf.String()
            execArgs = append(execArgs, "-d", jsonStr)
            displayParts = append(displayParts, "-d", shellQuote(jsonStr))
        }
    }

    if finalCurlURL != "" {
        execArgs = append(execArgs, finalCurlURL)
        displayParts = append(displayParts, shellQuote(finalCurlURL))
    }

    execArgs = append(execArgs, "-s", "-S")
    displayParts = append(displayParts, "-s", "-S")

    if prettyFlag {
        execArgs = append(execArgs, "-v")
        displayParts = append(displayParts, "-v")
    }

    if !jsonDataPresent {
        execArgs = append(execArgs, "-d@-")
        displayParts = append(displayParts, "-d@-")
    }

    if !hasContentType {
        omit := false
        if formMode {
            if len(formDataItems) > 0 {
                omit = true
            }
            for _, co := range curlOpts {
                if co == "-F" || co == "--form" {
                    omit = true
                    break
                }
            }
        }
        if !omit {
            execArgs = append(execArgs, "-H", "Content-Type: application/json")
            displayParts = append(displayParts, "-H", shellQuote("Content-Type: application/json"))
        }
    }
    if !hasAccept {
        execArgs = append(execArgs, "-H", "Accept: application/json, */*")
        displayParts = append(displayParts, "-H", shellQuote("Accept: application/json, */*"))
    }

    if curlFlag {
        curlCmdStr := strings.Join(displayParts, " ")
        if urlParseError != "" {
            fmt.Fprint(os.Stdout, urlParseError)
            fmt.Fprintln(os.Stdout, curlCmdStr)
        } else {
            fmt.Fprintln(os.Stdout, curlCmdStr)
        }
        if finalDisplayURL != "" {
            fmt.Fprintln(os.Stderr, finalDisplayURL)
        }
        os.Exit(0)
    }

    if finalDisplayURL != "" {
        fmt.Fprintln(os.Stderr, finalDisplayURL)
    }

    cmd := exec.Command("curl", execArgs...)
    var stdoutBuf bytes.Buffer
    var stderrBuf bytes.Buffer
    cmd.Stdout = &stdoutBuf
    cmd.Stderr = &stderrBuf
    cmd.Stdin = os.Stdin

    err := cmd.Run()
    body := stdoutBuf.Bytes()
    curlStderr := stderrBuf.String()

    isVerbose := false
    for _, o := range curlOpts {
        if o == "-v" || o == "--verbose" {
            isVerbose = true
            break
        }
    }

    if prettyFlag {
        var js interface{}
        if json.Unmarshal(body, &js) == nil {
            prettyBody := prettyPrintJSONWithColors(body)
            os.Stdout.Write(prettyBody)
        } else {
            os.Stdout.Write(body)
        }
    } else {
        os.Stdout.Write(body)
    }

    if isVerbose && prettyFlag {
        colored := colorizeCurlVerbose(curlStderr, true, true)
        fmt.Fprint(os.Stderr, colored)
    } else if isVerbose && !prettyFlag {
        fmt.Fprint(os.Stderr, curlStderr)
    } else if !isVerbose && prettyFlag {
        colored := colorizeCurlVerbose(curlStderr, false, true)
        fmt.Fprint(os.Stderr, colored)
    }

    if err != nil {
        if exitErr, ok := err.(*exec.ExitError); ok {
            os.Exit(exitErr.ExitCode())
        } else {
            fmt.Fprintln(os.Stderr, err)
            os.Exit(1)
        }
    }
}

func prettyPrintJSONWithColors(data []byte) []byte {
    white := "\x1b[37m"
    var out bytes.Buffer

    start := 0
    for start < len(data) && (data[start] == ' ' || data[start] == '\n' || data[start] == '\r' || data[start] == '\t') {
        start++
    }
    if start >= len(data) {
        return data
    }

    var writeVal func(pos int, indent int, isObjVal bool, isArrElem bool) int

    writeIndent := func(level int) {
        out.WriteString(strings.Repeat("    ", level))
    }

    writeVal = func(pos int, indent int, isObjVal bool, isArrElem bool) int {
        for pos < len(data) && (data[pos] == ' ' || data[pos] == '\n' || data[pos] == '\r' || data[pos] == '\t') {
            pos++
        }
        if pos >= len(data) {
            return pos
        }
        ch := data[pos]
        switch ch {
        case '{':
            out.WriteString(white + "{" + "\n")
            pos++
            for {
                for pos < len(data) && (data[pos] == ' ' || data[pos] == '\n' || data[pos] == '\r' || data[pos] == '\t') {
                    pos++
                }
                if pos < len(data) && data[pos] == '}' {
                    pos++
                    break
                }
                if pos >= len(data) || data[pos] != '"' {
                    break
                }
                endQuote := pos + 1
                for endQuote < len(data) {
                    if data[endQuote] == '"' {
                        bs := 0
                        k := endQuote - 1
                        for k >= pos && data[k] == '\\' {
                            bs++
                            k--
                        }
                        if bs%2 == 0 {
                            break
                        }
                    }
                    endQuote++
                }
                keyStr := string(data[pos : endQuote+1])
                writeIndent(indent + 1)
                out.WriteString("\x1b[34m" + keyStr + white + ": ")
                pos = endQuote + 1
                for pos < len(data) && (data[pos] == ' ' || data[pos] == '\n' || data[pos] == '\r' || data[pos] == '\t') {
                    pos++
                }
                if pos < len(data) && data[pos] == ':' {
                    pos++
                }
                for pos < len(data) && (data[pos] == ' ' || data[pos] == '\n' || data[pos] == '\r' || data[pos] == '\t') {
                    pos++
                }
                pos = writeVal(pos, indent+1, true, false)
                for pos < len(data) && (data[pos] == ' ' || data[pos] == '\n' || data[pos] == '\r' || data[pos] == '\t') {
                    pos++
                }
                if pos < len(data) && data[pos] == ',' {
                    out.WriteString(",\n")
                    pos++
                    continue
                } else if pos < len(data) && data[pos] == '}' {
                    out.WriteString("\n")
                    continue
                } else {
                    out.WriteString("\n")
                }
            }
            writeIndent(indent)
            out.WriteString(white + "}")
            return pos
        case '[':
            out.WriteString(white + "[" + "\n")
            pos++
            for {
                for pos < len(data) && (data[pos] == ' ' || data[pos] == '\n' || data[pos] == '\r' || data[pos] == '\t') {
                    pos++
                }
                if pos < len(data) && data[pos] == ']' {
                    pos++
                    break
                }
                writeIndent(indent + 1)
                pos = writeVal(pos, indent+1, false, true)
                for pos < len(data) && (data[pos] == ' ' || data[pos] == '\n' || data[pos] == '\r' || data[pos] == '\t') {
                    pos++
                }
                if pos < len(data) && data[pos] == ',' {
                    out.WriteString(",\n")
                    pos++
                    continue
                } else if pos < len(data) && data[pos] == ']' {
                    out.WriteString("\n")
                    continue
                } else {
                    out.WriteString("\n")
                }
            }
            writeIndent(indent)
            out.WriteString(white + "]")
            return pos
        case '"':
            endQuote := pos + 1
            for endQuote < len(data) {
                if data[endQuote] == '"' {
                    bs := 0
                    k := endQuote - 1
                    for k >= pos && data[k] == '\\' {
                        bs++
                        k--
                    }
                    if bs%2 == 0 {
                        break
                    }
                }
                endQuote++
            }
            str := string(data[pos : endQuote+1])
            if isObjVal {
                out.WriteString("\x1b[36m" + str + white)
            } else if isArrElem {
                out.WriteString("\x1b[34m" + str + white)
            } else {
                out.WriteString("\x1b[36m" + str + white)
            }
            return endQuote + 1
        case 't':
            if strings.HasPrefix(string(data[pos:]), "true") {
                if isObjVal {
                    out.WriteString("\x1b[35mtrue" + white)
                } else {
                    if isArrElem {
                        out.WriteString("true")
                    } else {
                        out.WriteString("\x1b[35mtrue" + white)
                    }
                }
                return pos + 4
            }
        case 'f':
            if strings.HasPrefix(string(data[pos:]), "false") {
                if isObjVal {
                    out.WriteString("\x1b[35mfalse" + white)
                } else {
                    if isArrElem {
                        out.WriteString("false")
                    } else {
                        out.WriteString("\x1b[35mfalse" + white)
                    }
                }
                return pos + 5
            }
        case 'n':
            if strings.HasPrefix(string(data[pos:]), "null") {
                if isObjVal {
                    out.WriteString("\x1b[35mnull" + white)
                } else {
                    if isArrElem {
                        out.WriteString("null")
                    } else {
                        out.WriteString("\x1b[35mnull" + white)
                    }
                }
                return pos + 4
            }
        default:
            end := pos
            for end < len(data) && ((data[end] >= '0' && data[end] <= '9') || data[end] == '-' || data[end] == '.' || data[end] == 'e' || data[end] == 'E' || data[end] == '+') {
                end++
            }
            numStr := string(data[pos:end])
            if isObjVal {
                out.WriteString("\x1b[36m" + numStr + white)
            } else {
                if isArrElem {
                    out.WriteString(numStr)
                } else {
                    out.WriteString("\x1b[36m" + numStr + white)
                }
            }
            return end
        }
        return pos
    }

    writeVal(start, 0, false, false)
    out.WriteString("\x1b[0m\n")
    return out.Bytes()
}

func colorizeCurlVerbose(input string, showAll bool, useColors bool) string {
    var out strings.Builder
    lines := strings.Split(input, "\n")
    for _, line := range lines {
        if !showAll {
            if strings.HasPrefix(line, "<") {
                content := strings.TrimPrefix(line, "<")
                content = strings.TrimSpace(content)
                if content == "" {
                    out.WriteString("\r\n")
                    continue
                }
                if useColors {
                    out.WriteString(colorizeHeaderLine(content))
                } else {
                    out.WriteString(content + "\r\n")
                }
            }
        } else {
            if strings.HasPrefix(line, "*") {
                content := strings.TrimPrefix(line, "*")
                content = strings.TrimSpace(content)
                if useColors {
                    out.WriteString("\x1b[90m*   " + content + "\x1b[0m\n")
                } else {
                    out.WriteString("*   " + content + "\n")
                }
            } else if strings.HasPrefix(line, ">") {
                content := strings.TrimPrefix(line, ">")
                content = strings.TrimSpace(content)
                if content == "" {
                    out.WriteString("\r\n")
                    continue
                }
                if useColors {
                    if strings.Contains(content, "HTTP/") && (strings.HasPrefix(content, "GET") || strings.HasPrefix(content, "POST") || strings.HasPrefix(content, "PUT") || strings.HasPrefix(content, "DELETE") || strings.HasPrefix(content, "PATCH") || strings.HasPrefix(content, "HEAD") || strings.HasPrefix(content, "OPTIONS") || strings.HasPrefix(content, "TRACE")) {
                        out.WriteString(colorizeRequestLine(content))
                    } else {
                        out.WriteString(colorizeHeaderLine(content))
                    }
                } else {
                    out.WriteString(content + "\n")
                }
            } else if strings.HasPrefix(line, "<") {
                content := strings.TrimPrefix(line, "<")
                content = strings.TrimSpace(content)
                if content == "" {
                    out.WriteString("\r\n")
                    continue
                }
                if useColors {
                    out.WriteString(colorizeHeaderLine(content))
                } else {
                    out.WriteString(content + "\n")
                }
            }
        }
    }
    return out.String()
}

func colorizeHeaderLine(line string) string {
    white := "\x1b[37m"
    blue := "\x1b[34m"
    cyan := "\x1b[36m"
    yellow := "\x1b[33m"
    reset := "\x1b[0m"

    if strings.HasPrefix(line, "HTTP/") {
        idx := strings.Index(line, "/")
        if idx != -1 {
            rest := line[idx+1:]
            parts := strings.Fields(rest)
            version := ""
            code := ""
            reason := ""
            if len(parts) >= 1 {
                version = parts[0]
            }
            if len(parts) >= 2 {
                code = parts[1]
            }
            if len(parts) > 2 {
                reason = strings.Join(parts[2:], " ")
            }
            var out strings.Builder
            out.WriteString(blue + "HTTP" + white + "/" + cyan + version + " " + code)
            if reason != "" {
                out.WriteString(yellow + " " + reason)
            }
            out.WriteString("\r" + reset + "\n")
            return out.String()
        }
    }
    parts := strings.Split(line, " ")
    if len(parts) >= 3 && strings.HasPrefix(parts[2], "HTTP/") {
        method := parts[0]
        path := parts[1]
        httpPart := parts[2]
        var httpOut strings.Builder
        if idx := strings.Index(httpPart, "/"); idx != -1 {
            httpOut.WriteString(blue + "HTTP" + white + "/" + cyan + httpPart[idx+1:])
        } else {
            httpOut.WriteString(httpPart)
        }
        var out strings.Builder
        out.WriteString(blue + method + white + " " + path + " " + httpOut.String() + "\r" + reset + "\n")
        return out.String()
    }
    if colonIdx := strings.Index(line, ":"); colonIdx != -1 {
        name := line[:colonIdx+1]
        value := line[colonIdx+1:]
        var out strings.Builder
        out.WriteString(white + name + cyan + value + "\r" + reset + "\n")
        return out.String()
    }
    return white + line + "\r" + reset + "\n"
}

func colorizeRequestLine(line string) string {
    return colorizeHeaderLine(line)
}
